Set(
    varUserDirectorate,
    varCurrentUserRecord.Directorate
);

Set(
    varUserDirectorateID,
    varCurrentUserRecord.Directorate.Id
);



// Report permissions
Set(
    varCanViewAllReports,
    varUserRole = "DeputyDirectorME" ||
    varUserRole = "Administrator"
);


// ============================================================
// 6. NOTIFICATIONS
// ============================================================

ClearCollect(
    colMyNotifications,
    Filter(
        Notifications,
        RecipientUser.Email = User().Email &&
        IsRead = false
    )
);

Set(
    varUnreadCount,
    CountRows(colMyNotifications)
);


// ============================================================
