        Month(Today()) >= 4,
        Text(Year(Today())) &
        "/" &
        Text(
            Mod(Year(Today()) + 1, 100),
            "00"
        ),
        Text(Year(Today()) - 1) &
        "/" &
        Text(
            Mod(Year(Today()), 100),
            "00"
        )
    )
);


