    Switch(
        Month(Today()),
        1, "January",
        2, "February",
        3, "March",
        4, "April",
        5, "May",
        6, "June",
        7, "July",
        8, "August",
        9, "September",
        10, "October",
        11, "November",
        12, "December"
    )
);


// ============================================================
// 9. CURRENT QUARTER
// ============================================================

Set(
    varCurrentQuarter,
    Switch(
        true,
        Month(Today()) >= 4 &&
        Month(Today()) <= 6,
        "Q1 (Apr-Jun)",

        Month(Today()) >= 7 &&
        Month(Today()) <= 9,
        "Q2 (Jul-Sep)",

        Month(Today()) >= 10 &&
        Month(Today()) <= 12,
        "Q3 (Oct-Dec)",

        "Q4 (Jan-Mar)"
    )
);


// ============================================================
// 10. DATE
// ============================================================

Set(
    varTodaysDate,
    Today()
);


// ============================================================
// 11. UI STATE
// ============================================================

Set(varNavOpen, false);
